/**
 * ADR-0575 stream core generator (tools/publishing/generate-node-streams.mjs): what it does to
 * Node's text, and that a changed byte reds. Whole modules are the vendored file unedited; a
 * selected module is upstream statements unedited, in upstream order, between the generator's
 * own three parts (narrowed `primordials` header, `PRELUDE`, `module.exports`). The committed
 * output equals a fresh run (no minifier: it would drop function names); a vendored byte, a
 * generated byte or a new upstream input reds; the generated functions have Node's names.
 */
import { spawnSync } from 'node:child_process';
import { cpSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterAll, describe, expect, it } from 'vitest';
import {
  PINS,
  PRELUDE,
  VENDOR,
  acorn,
  buildNodeStreams,
  generate,
} from '../publishing/generate-node-streams.mjs';

const OUT = 'packages/io/src/streams/node/generated';
const tmp = mkdtempSync(join(tmpdir(), 'node-streams-gen-'));
afterAll(() => rmSync(tmp, { recursive: true, force: true }));
const vendored = (id: string) => readFileSync(join(VENDOR, `lib/${id}.js`), 'utf8');
/** A vendor copy with `edit` applied to one file. */
function vendorWith(path: string, edit: (text: string) => string): string {
  const dir = mkdtempSync(join(tmp, 'vendor-'));
  cpSync(VENDOR, dir, { recursive: true });
  writeFileSync(join(dir, path), edit(readFileSync(join(dir, path), 'utf8')));
  return dir;
}

describe('node-streams generator', () => {
  it('the committed output is a fresh run (check:node-streams-drift)', async () => {
    await expect(generate('--check', { out: OUT })).resolves.toBeDefined();
  });

  it('whole modules: the vendored file, unedited', async () => {
    const { modules } = await buildNodeStreams();
    const whole = modules.filter((m: { kind: string }) => m.kind === 'whole');
    expect(whole).toHaveLength(23);
    for (const m of whole) expect(m.text, m.id).toBe(vendored(m.id));
  });

  it('selected modules: upstream statements unedited, in order, between the three generated parts', async () => {
    const { modules } = await buildNodeStreams();
    const selected = modules.filter((m: { kind: string }) => m.kind === 'selected');
    expect(selected.map((m: { id: string }) => m.id).sort()).toEqual(Object.keys(PRELUDE).sort());
    for (const { id, text } of selected) {
      const upstream = vendored(id);
      const head = /^'use strict';\n(?:const \{\n(?: {2}\w+,\n)+\} = primordials;\n)?/.exec(text);
      expect(head, id).not.toBeNull();
      const prelude = PRELUDE[id as keyof typeof PRELUDE];
      const rest = text.slice((head as RegExpExecArray)[0].length);
      expect(rest.startsWith(prelude), id).toBe(true);
      // Each prelude line narrows an upstream require of the same id to names it destructures.
      for (const line of prelude.split('\n').filter(Boolean)) {
        const [, names, from] = /^const \{ ([\w, ]+) \} = require\('([\w/]+)'\);$/.exec(line) ?? [];
        expect(from, line).toBeDefined();
        const upstreamNames = [
          ...upstream.matchAll(new RegExp(`const \\{([^}]*)\\} = require\\('${from}'\\)`, 'g')),
        ].flatMap((m) => (m[1] as string).split(',').map((n) => n.trim()));
        if (id !== 'internal/url')
          for (const n of (names as string).split(', ')) expect(upstreamNames, line).toContain(n);
      }
      const exports = /\nmodule\.exports = \{ [\w, ]+ \};\n$/.exec(rest);
      expect(exports, id).not.toBeNull();
      const body = rest.slice(prelude.length, rest.length - (exports as RegExpExecArray)[0].length);
      let at = 0;
      for (const st of acorn.parse(body, { ecmaVersion: 'latest', sourceType: 'script' }).body) {
        const piece = body.slice(st.start, st.end);
        const found = upstream.indexOf(piece, at);
        expect(found, `${id}: ${piece.slice(0, 60)}`).toBeGreaterThanOrEqual(at);
        at = found + piece.length;
      }
    }
  });

  it("after generation, every function reachable from a module's exports has Node's name and length", () => {
    const r = spawnSync(
      process.execPath,
      ['--expose-internals', 'tests/integration/node-streams-differential/names-vs-node.cjs'],
      { encoding: 'utf8' },
    );
    expect(r.status, r.stderr).toBe(0);
    expect(JSON.parse(r.stdout)).toEqual([]);
  });

  it('a changed vendored byte is drift', async () => {
    const dir = vendorWith('lib/internal/streams/readable.js', (t) =>
      t.replace('highWaterMark', 'highWaterMarK'),
    );
    await expect(buildNodeStreams(dir)).rejects.toThrow(
      /Node source drift: lib\/internal\/streams\/readable\.js/,
    );
  });

  it('a changed generated byte is drift', async () => {
    const out = mkdtempSync(join(tmp, 'out-'));
    cpSync(OUT, out, { recursive: true });
    const file = join(out, 'node-streams.js');
    writeFileSync(file, readFileSync(file, 'utf8').replace('highWaterMark', 'highWaterMarK'));
    await expect(generate('--check', { out })).rejects.toThrow(
      /node-streams drift: node-streams\.js/,
    );
  });

  it('a new upstream input (require id, internalBinding, global) is drift, not a silent binding gap', async () => {
    for (const [edit, what] of [
      [(t: string) => `${t}\nrequire('internal/new_binding');\n`, 'bindings'],
      [(t: string) => `${t}\ninternalBinding('new');\n`, 'internalBindings'],
      [(t: string) => `${t}\nqueueMicrotask(() => {});\n`, 'hostGlobals'],
    ] as const) {
      const path = 'lib/internal/streams/legacy.js';
      const dir = vendorWith(path, edit);
      const text = readFileSync(join(dir, path), 'utf8');
      const { createHash } = await import('node:crypto');
      const pins = { ...PINS, [path]: createHash('sha256').update(text).digest('hex') };
      await expect(buildNodeStreams(dir, pins), what).rejects.toThrow(
        new RegExp(`node-streams anchor drift: ${what} `),
      );
    }
  });
});
